    name="get_profile_card",
    title="Get Profile Card",
    description="Get a profile card for a Slack user by their user ID.",
    annotations=ToolAnnotations(read_only_hint=True),
)
async def get_profile_card(
    user_id: str,
    ctx: Context,
) -> CallToolResult:
    meta: dict[str, Any] = dict(ctx.request_context.meta or {})
    slack = meta.get("slack") or {}

    if not slack.get("user_id") or not slack.get("team_id"):
        return CallToolResult(
            content=[
                TextContent(
                    type="text",
                    text="Missing Slack identity context. This tool must be called from Slack.",
                )
            ],
        )

    installation = installation_store.find_installation(
        enterprise_id=slack.get("enterprise_id"),
        team_id=slack["team_id"],
        user_id=slack["user_id"],
        is_enterprise_install=bool(slack.get("enterprise_id")),
    )
    if not installation or not installation.bot_token:
        install_url = f"{os.environ.get('BASE_URL', '')}/slack/install"
        return CallToolResult(
            content=[
                TextContent(
                    type="text",
                    text=f"App not installed to this workspace. Please install first: {install_url}",
                )
            ],
        )

    try:
        client = WebClient(token=installation.bot_token)
        result = client.users_info(user=user_id)
        profile = (result["user"] or {}).get("profile")
        if not profile:
            raise ValueError("No profile found")
    except (SlackApiError, ValueError, KeyError):
        return CallToolResult(
            content=[
                TextContent(
                    type="text",
                    text=f"Failed to fetch profile for {user_id}.",
                )
            ],
        )

    return CallToolResult(
        content=[
            TextContent(
                type="text",
                text=f"Profile card for {profile['real_name']}\n"
                f"Title: {profile.get('title', '')}\n"
                f"Email: {profile.get('email', '')}",
            )
        ],
    )


