## Example {#example}

*   JSON
*   Python Slack SDK
*   Node Slack SDK
*   Java Slack SDK

```
{  "type": "rich_text",  "elements": [    {      "type": "rich_text_section",      "elements": [        {          "type": "text",          "text": "Hello there, "        },        {          "type": "text",          "text": "I am a bold rich text block!",          "style": {            "bold": true          }        }      ]    }  ]}
```

[View in Block Kit Builder](https://app.slack.com/block-kit-builder/#%7B%2522blocks%2522%3A%255B%257B%2522type%2522%3A%2522rich_text%2522%2C%2522elements%2522%3A%255B%257B%2522type%2522%3A%2522rich_text_section%2522%2C%2522elements%2522%3A%255B%257B%2522type%2522%3A%2522text%2522%2C%2522text%2522%3A%2522Hello%2520there%2C%2520%2522%257D%2C%257B%2522type%2522%3A%2522text%2522%2C%2522text%2522%3A%2522I%2520am%2520a%2520bold%2520rich%2520text%2520block%21%2522%2C%2522style%2522%3A%257B%2522bold%2522%3Atrue%257D%257D%255D%257D%255D%257D%255D%257D)

```python
def example01() -> RichTextBlock:
    """
    Displays text, optionally with styling.
    https://docs.slack.dev/reference/block-kit/block-elements/text-element/

    A rich text block with plain and bold text elements in a section.
    """
    block = RichTextBlock(
        elements=[
            RichTextSectionElement(
                elements=[
                    RichTextElementParts.Text(text="Hello there, "),
                    RichTextElementParts.Text(
                        text="I am a bold rich text block!",
                        style=RichTextElementParts.TextStyle(bold=True),
                    ),
                ]
            )
        ]
    )
    return block
```

```javascript
export function example01() {
  /**
   * @type {import('@slack/types').RichTextBlock}
   */
  const block = {
    type: "rich_text",
    elements: [
      {
        type: "rich_text_section",
        elements: [
          {
            type: "text",
            text: "Hello there, ",
          },
          {
            type: "text",
            text: "I am a bold rich text block!",
            style: {
              bold: true,
            },
          },
        ],
      },
    ],
  };
  return block;
}
```

```java
public static RichTextBlock example01() {
    RichTextBlock block = Blocks.richText(rt -> rt.elements(List.of(RichTextSectionElement.builder()
            .elements(List.of(
                    RichTextSectionElement.Text.builder()
                            .text("Hello there, ")
                            .build(),
                    RichTextSectionElement.Text.builder()
                            .text("I am a bold rich text block!")
                            .style(TextStyle.builder().bold(true).build())
                            .build()))
            .build())));
    return block;
}
```

