### 3. Define the main function {#define-main-function}

This function uses the filters previously created to automatically sort invites.

The `BLOCKED_EMAIL_DOMAINS` values are denied, the `ALLOWED_EMAIL_DOMAINS` values are approved, and the the `REQUEST_REASON_EMAIL_DOMAINS` values are followed up with a prompt asking for additional information with the info set up in the previous instruction step using a [Block Kit actions handler](https://docs.slack.dev/tools/deno-slack-sdk/guides/creating-an-interactive-modal.md#open-block-kit-action).

```
export default SlackFunction(RequestInfoFunction,  async ({ inputs, tokens, env }) => {    const invitees = inputs.invite_request.target_users;    const client = SlackAPI(token, { slackApiUrl: env.SLACK_API_URL });    // Filter invitees based on email domain.    const denyInvites = filterInvites(invitees, BLOCKED_EMAIL_DOMAINS);    const approveInvites = filterInvites(invitees, ALLOWED_EMAIL_DOMAINS);    const requiresReasonInvites = filterInvites(invitees, REQUEST_REASON_EMAIL_DOMAINS);    await handleInvites(client, approveInvites, "approve");    await handleInvites(client, denyInvites, "deny", "The recipients are not part of a pre-approved organization to work with.");    // Auto-approve or deny based on blocked or allow domain criteria.    // Prompt for more information if meets needs more info status.    if (requiresReasonInvites.length) {       const userId = inputs.invite_request.actor.id;       await postReasonRequestMessage(client, inputs.invite_request.actor.id);    }   return { completed: false }; },) .addBlockActionsHandler(   "open_form",   async ({ inputs: _inputs, body, token, env }) => {	const formMetadata = {	  ts: body?.message?.ts ?? "",	  message_channel_id: body?.channel?.id ?? "",	};     // Handle button click to open a form for additional information.     const client = SlackAPI(token, { slackApiUrl: env.SLACK_API_URL });     // Build form that requests a reason for the invite     const view_payload = {	interactivity_pointer: body.interactivity.interactivity_pointer,       view: {	  private_metadata: JSON.stringify(formMetadata),	  type: "modal",	  title: {		type: "plain_text",		text: "Details about the Connecting Teams",		},	  submit: {		type: "plain_text",		text: "Submit",	  },	  blocks: [		{		  "type": "section",		  "text": {			"type": "mrkdwn",			"text": "Additional information",		  },		},		{		  "type": "divider",		},		{		  "type": "input",		  "block_id": "reason_block",		  "element": {			"type": "plain_text",			"action_id": "reason_input",			"multiline": true,			"placeholder": {				"type": "plain_text",				"text": "Please provide a reason for this invitation.",			},		  },		  "label": {			"type": "plain_text",			"text": "Reason",		  },		},	  ],	}     };  }, ) .addViewSubmissionHandler(   "approval_info_modal",   async ({ body, view, token, env, inputs }) => { 	// Handle View Submission	// Update the Slackbot message to end workflow submissions	const privateMetadata = JSON.parse(view.private_metadata ?? "");	const client = SlackAPI(token, {	  slackApiUrl: env.SLACK_API_URL,	});      // Update message to user to show that submission was made with the reason	const resp = await client.chat.update({	  channel: privateMetadata.message_channel_id,	  ts: privateMetadata.ts,	  as_user: true,	  text: "Provide more info about SC channel request",	  blocks: [		{		  "type": "header",		  "text": {			"type": "plain_text",			"text": "Slack Connect Approval Details",		  },		},		{		  "type": "context",		  "elements": [{  "type": "mrkdwn",  "text": "Thank you for your submission :white_check_mark:",			},		  ],		},	  ],	});	// TODO: Handle user input in the way you want	const reasonForInviteRequest = view.state.values.reason_block.reason_input.value;  },);
