import com.slack.api.methods.response.views.ViewsPublishResponse;import com.slack.api.model.event.AppHomeOpenedEvent;import com.slack.api.model.view.View;import java.time.ZonedDateTime;import static com.slack.api.model.block.Blocks.*;import static com.slack.api.model.block.composition.BlockCompositions.*;import static com.slack.api.model.view.Views.*;// /reference/events/app_home_openedapp.event(AppHomeOpenedEvent.class, (payload, ctx) -> {  // Build a Home tab view  ZonedDateTime now = ZonedDateTime.now();  View appHomeView = view(view -> view    .type("home")    .blocks(asBlocks(      section(section -> section.text(markdownText(mt -> mt.text(":wave: Hello, App Home! (Last updated: " + now + ")")))),      image(img -> img.imageUrl("https://www.example.com/foo.png").altText("alt text for image"))    ))  );  // Update the App Home for the given user  if (payload.getEvent().getView() == null) {    ViewsPublishResponse res = ctx.client().viewsPublish(r -> r      .userId(payload.getEvent().getUser())      .view(appHomeView)    );  } else {    ViewsPublishResponse res = ctx.client().viewsPublish(r -> r      .userId(payload.getEvent().getUser())      .hash(payload.getEvent().getView().getHash()) // To safeguard against potential race conditions      .view(appHomeView)    );  }  return ctx.ack();});
```

It looks like this in Kotlin. (New to Kotlin? [Getting Started in Kotlin](https://docs.slack.dev/tools/java-slack-sdk/guides/getting-started-with-bolt.md#getting-started-in-kotlin) may be helpful.)

```
// static importsimport com.slack.api.model.block.Blocks.*import com.slack.api.model.block.composition.BlockCompositions.*import com.slack.api.model.view.Views.*import com.slack.api.model.event.AppHomeOpenedEventimport java.time.ZonedDateTime// /reference/events/app_home_openedapp.event(AppHomeOpenedEvent::class.java) { event, ctx ->  // Build a Home tab view  val now = ZonedDateTime.now()  val appHomeView = view {    it.type("home")      .blocks(asBlocks(        section { section -> section.text(markdownText { mt -> mt.text(":wave: Hello, App Home! (Last updated: ${now})") }) },        image { img -> img.imageUrl("https://www.example.com/foo.png").altText("alt text for image") }      ))  }  // Update the App Home for the given user  val res = ctx.client().viewsPublish {    it.userId(event.event.user)      .hash(event.event.view?.hash) // To protect against possible race conditions       .view(appHomeView)  }  ctx.ack()}
```

You can also build the view in the above example with the [Block Kit Kotlin DSL](https://docs.slack.dev/tools/java-slack-sdk/guides/composing-messages.md#block-kit-kotlin-dsl) like so:

```
// These imports are necessary for this codeimport com.slack.api.model.kotlin_extension.view.blocksimport com.slack.api.model.view.Views.viewval appHomeView = view { it  .type("home")  .blocks {    section {      markdownText(":wave: Hello, App Home! (Last updated: ${now}")    }    image {      imageUrl("https://www.example.com/foo.png")    }  }}
```

## Examples {#examples}

Check [the Servlet app example](https://github.com/slackapi/java-slack-sdk/blob/main/bolt-servlet/src/test/java/samples/OpenIDConnectSample.java) to learn how to implement your web app that handles the OpenID Connect flow with end-users.

```
import java.util.*;// implementation 'com.slack.api:bolt-jetty:{the latest version}'import com.slack.api.Slack;import com.slack.api.bolt.App;import com.slack.api.bolt.jetty.SlackAppServer;// If you want to decode the JWT id_token, you can use the following external library for it:// implementation 'com.auth0:java-jwt:{the latest version}'import com.auth0.jwt.JWT;import com.auth0.jwt.interfaces.Claim;import com.auth0.jwt.interfaces.DecodedJWT;// The following env variables are supposed to be set:// SLACK_CLIENT_ID, SLACK_CLIENT_SECRET, SLACK_REDIRECT_URI, SLACK_USER_SCOPESApp app = new App().asOpenIDConnectApp(true);// You can handle the OpenID Connect code authorization flow with this callback functionapp.openIDConnectSuccess((req, resp, token) -> {  var logger = req.getContext().getLogger();    // TODO: Store the given "token" response (openid.connect.token API response)  // Decode id_token in an openid.connect.token response  DecodedJWT decoded = JWT.decode(token.getIdToken());  Map<String, Claim> claims = decoded.getClaims();  logger.info("claims: {}", claims);  var teamId = claims.get("https://slack.com/team_id").asString();  // Code example demonstrating how to call openid.connect.userInfo using the given access token  var client = Slack.getInstance().methods();  try {    var userInfo = client.openIDConnectUserInfo(r -> r.token(token.getAccessToken()));    logger.info("userInfo: {}", userInfo);  } catch (Exception e) {    throw new RuntimeException(e);  }  // Render a web page for the user (or you can redirect the user to the next step such as OAuth with other services)  var html = app.config().getOAuthRedirectUriPageRenderer().renderSuccessPage(    null, req.getContext().getOauthCompletionUrl());  resp.setBody(html);  resp.setContentType("text/html; charset=utf-8");  return resp;});Map<String, App> apps = new HashMap<>();apps.put("/slack/", app);SlackAppServer server = new SlackAppServer(apps);server.start();
```

